import React, { useState, useEffect, useRef } from 'react';
import './Carrusel.css';

export default function Carrusel() {
  const [slides, setSlides] = useState([]); 
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [cargando, setCargando] = useState(true);
  const intervalRef = useRef(null);
  const timeoutRef = useRef(null);

  useEffect(() => {
    fetch('http://localhost:8080/api/productos') 
      .then((res) => res.json())
      .then((data) => {
        const productosConImagen = data
          .filter(p => p.imagen || p.foto)
          .slice(0, 4)
          .map(p => ({
            image: p.imagen ? `http://localhost:8080/api/imagenes/${p.imagen}` : require("../assets/productos/1DEDO.jpg"),
            name: p.nombre,
            categoria: p.nombreCategoria || "Destacado"
          }));

        if (productosConImagen.length === 0) {
          setSlides([
            { image: require("../assets/productos/1DEDO.jpg"), name: '1DEDO - Limpieza de manos premium', categoria: 'Detallado' }
          ]);
        } else {
          setSlides(productosConImagen);
        }
        setCargando(false);
      })
      .catch((err) => {
        console.error("Error cargando imágenes del carrusel:", err);
        setSlides([
          { image: require("../assets/productos/1DEDO.jpg"), name: '1DEDO - Limpieza de manos premium (Offline)', categoria: 'Lubcker Pro' }
        ]);
        setCargando(false);
      });
  }, []);

  const nextSlide = () => {
    if (slides.length <= 1) return;
    resetPauseTimer();
    setCurrentSlide((prevSlide) => (prevSlide + 1) % slides.length);
  };

  const prevSlide = () => {
    if (slides.length <= 1) return;
    resetPauseTimer();
    setCurrentSlide((prevSlide) => (prevSlide - 1 + slides.length) % slides.length);
  };

  const irAlSlide = (index) => {
    resetPauseTimer();
    setCurrentSlide(index);
  };

  const resetPauseTimer = () => {
    setIsPaused(true);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      setIsPaused(false);
    }, 8000); 
  };

  useEffect(() => {
    if (slides.length <= 1) return;
    if (!isPaused) {
      intervalRef.current = setInterval(() => {
        setCurrentSlide((prevSlide) => (prevSlide + 1) % slides.length);
      }, 5000); // 5 segundos para lectura cómoda
    }

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [isPaused, slides]);

  if (cargando) {
    return (
      <div className="carrusel-contenedor" style={{color: '#aaa', textAlign: 'center', padding: '60px 20px', background: '#111'}}>
        <div className="spinner" style={{border: '3px solid #333', borderTop: '3px solid #28a745', borderRadius: '50%', width: '30px', height: '30px', animation: 'spin 1s linear infinite', margin: '0 auto 15px'}}></div>
        <p style={{fontSize: '14px', letterSpacing: '1px'}}>SINCRO DE OFERTAS LUBCKER...</p>
      </div>
    );
  }

  return (
    <div className="carrusel-contenedor" onClick={resetPauseTimer}>
      <div className="carrusel-viewport">
        <div className="carrusel-slides" style={{ transform: `translateX(-${currentSlide * 100}%)` }}>
          {slides.map((slide, index) => (
            <div className="carrusel-slide" key={index}>
              <img src={slide.image} alt={slide.name} className="carrusel-image" />
              <div className="carrusel-overlay">
                <span className="carrusel-tag">{slide.categoria}</span>
                <p className="carrusel-name">{slide.name}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Flechas estilizadas mediante vectores SVG puros */}
      {slides.length > 1 && (
        <>
          <button className="carrusel-btn carrusel-prev" onClick={prevSlide} aria-label="Anterior">
            <svg viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6"></polyline></svg>
          </button>
          <button className="carrusel-btn carrusel-next" onClick={nextSlide} aria-label="Siguiente">
            <svg viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"></polyline></svg>
          </button>

          {/* Barra indicadora inferior interactiva (Dots) */}
          <div className="carrusel-dots">
            {slides.map((_, index) => (
              <button
                key={index}
                className={`carrusel-dot ${index === currentSlide ? 'active' : ''}`}
                onClick={() => irAlSlide(index)}
                aria-label={`Ir al slide ${index + 1}`}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
}
